import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.spec.*;
import java.util.*;
import java.util.zip.*;
import javax.crypto.*;
import javax.crypto.spec.*;

final class AnalysisEngine {
    static byte[] pipeline(byte[] input,String spec)throws Exception{byte[] value=input;for(String command:spec.split("\\|")){String c=command.strip();ByteArrayOutputStream out=new ByteArrayOutputStream();switch(c){case "","identity"->{}case "base64.encode"->value=Base64.getEncoder().encode(value);case "base64.decode"->value=Base64.getDecoder().decode(value);case "hex.encode"->value=HexFormat.of().formatHex(value).getBytes(StandardCharsets.US_ASCII);case "hex.decode"->value=HexFormat.of().parseHex(new String(value,StandardCharsets.US_ASCII).replaceAll("\\s+",""));case "url.encode"->value=java.net.URLEncoder.encode(new String(value,StandardCharsets.UTF_8),StandardCharsets.UTF_8).getBytes(StandardCharsets.UTF_8);case "url.decode"->value=java.net.URLDecoder.decode(new String(value,StandardCharsets.UTF_8),StandardCharsets.UTF_8).getBytes(StandardCharsets.UTF_8);case "gzip.encode","deflate.encode"->{try(OutputStream zip=c.startsWith("gzip")?new GZIPOutputStream(out):new DeflaterOutputStream(out)){zip.write(value);}value=out.toByteArray();}case "gzip.decode","deflate.decode"->{try(InputStream zip=c.startsWith("gzip")?new GZIPInputStream(new ByteArrayInputStream(value)):new InflaterInputStream(new ByteArrayInputStream(value))){value=zip.readNBytes(VulnApp.MAX_BODY+1);}}case "sha256"->value=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value)).getBytes(StandardCharsets.US_ASCII);default->throw new IllegalArgumentException("Unknown pipeline step: "+c);}if(value.length>VulnApp.MAX_BODY)throw new IOException("Pipeline output exceeds 10 MiB");}return value;}
    static String jwt(String token,String key,boolean verify)throws Exception{String[] parts=token.strip().split("\\.",-1);if(parts.length!=3)throw new IllegalArgumentException("JWT requires three segments");Map<String,Object> header=Json.object(Json.parse(new String(Base64.getUrlDecoder().decode(parts[0]),StandardCharsets.UTF_8)));Object claims=Json.parse(new String(Base64.getUrlDecoder().decode(parts[1]),StandardCharsets.UTF_8));String status="Signature not verified";if(verify){String algorithm=String.valueOf(header.get("alg"));byte[] data=(parts[0]+"."+parts[1]).getBytes(StandardCharsets.US_ASCII),signature=Base64.getUrlDecoder().decode(parts[2]);boolean valid;switch(algorithm){case "HS256"->{if(key.contains("BEGIN"))throw new IllegalArgumentException("HMAC requires a shared secret, not a PEM public key");Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));valid=MessageDigest.isEqual(mac.doFinal(data),signature);}case "RS256"->{byte[] der=Base64.getDecoder().decode(key.replace("-----BEGIN PUBLIC KEY-----","").replace("-----END PUBLIC KEY-----","").replaceAll("\\s+",""));Signature verifier=Signature.getInstance("SHA256withRSA");verifier.initVerify(KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(der)));verifier.update(data);valid=verifier.verify(signature);}default->throw new IllegalArgumentException("Allowed verification algorithms: HS256, RS256");}status=valid?"VALID signature":"INVALID signature";}return status+"\nSignature verification does not validate issuer, audience or time claims.\n\nHEADER\n"+RequestWorkbench.pretty(Json.write(header))+"\n\nCLAIMS\n"+RequestWorkbench.pretty(Json.write(claims));}
    static String bytes(byte[] a,byte[] b){StringBuilder out=new StringBuilder();int differences=0;for(int i=0;i<Math.max(a.length,b.length);i++){int x=i<a.length?a[i]&255:-1,y=i<b.length?b[i]&255:-1;if(x!=y){differences++;if(differences<=20000)out.append(String.format("%08x  %s -> %s%n",i,x<0?"--":String.format("%02x",x),y<0?"--":String.format("%02x",y)));}}return "Byte differences: "+differences+" (first 20000 shown)\n"+out;}
    static String diff(String a,String b){String[] left=a.split("\\R",-1),right=b.split("\\R",-1);if(left.length>5000||right.length>5000)throw new IllegalArgumentException("Maximum 5000 lines");List<String> common=new ArrayList<>();lcs(left,0,left.length,right,0,right.length,common);StringBuilder out=new StringBuilder();int i=0,j=0;for(String line:common){while(i<left.length&&!left[i].equals(line))out.append("- ").append(left[i++]).append('\n');while(j<right.length&&!right[j].equals(line))out.append("+ ").append(right[j++]).append('\n');out.append("  ").append(line).append('\n');i++;j++;}while(i<left.length)out.append("- ").append(left[i++]).append('\n');while(j<right.length)out.append("+ ").append(right[j++]).append('\n');return out.toString();}
    static int[] lengths(String[] a,int start,int end,String[] b,int from,int to,boolean reverse){int n=to-from;int[] row=new int[n+1];for(int z=0;z<end-start;z++){int prior=0;String x=a[reverse?end-1-z:start+z];for(int k=1;k<=n;k++){int old=row[k];row[k]=x.equals(b[reverse?to-k:from+k-1])?prior+1:Math.max(row[k],row[k-1]);prior=old;}}return row;}
    static void lcs(String[] a,int start,int end,String[] b,int from,int to,List<String> out){if(start==end||from==to)return;if(end-start==1){for(int i=from;i<to;i++)if(a[start].equals(b[i])){out.add(a[start]);break;}return;}int mid=(start+end)/2,n=to-from;int[] x=lengths(a,start,mid,b,from,to,false),y=lengths(a,mid,end,b,from,to,true);int split=0;for(int i=1;i<=n;i++)if(x[i]+y[n-i]>x[split]+y[n-split])split=i;lcs(a,start,mid,b,from,from+split,out);lcs(a,mid,end,b,from+split,to,out);}
    static String statistics(List<String> tokens){StringBuilder out=new StringBuilder(WorkbenchCore.tokenAnalysis(tokens));byte[] data=String.join("",tokens).getBytes(StandardCharsets.UTF_8);long bits=(long)data.length*8,ones=0,runs=0;int previous=-1;for(byte value:data)for(int bit=7;bit>=0;bit--){int v=(value>>bit)&1;ones+=v;if(v!=previous)runs++;previous=v;}double p=bits==0?0:(double)ones/bits;double z=bits==0?0:Math.abs(2.0*ones-bits)/Math.sqrt(bits);double mean=bits==0?0:2*bits*p*(1-p);double runZ=bits==0||p==0||p==1?Double.POSITIVE_INFINITY:Math.abs(runs-mean)/(2*Math.sqrt(2*bits)*p*(1-p));int[] counts=new int[256];for(byte value:data)counts[value&255]++;double chi=0,expected=data.length/256.0;if(expected>0)for(int count:counts)chi+=(count-expected)*(count-expected)/expected;return out.append(String.format(Locale.ROOT,"\nBIT TESTS ON UTF-8 ENCODING\nBits: %d%nOne proportion: %.6f%nMonobit z: %.4f%nRuns: %d%nRuns deviation: %.4f%nByte chi-square (255 df): %.4f%n",bits,p,z,runs,runZ,chi)).append("Encoding strongly influences these values. Descriptive diagnostics, not a cryptographic certification.\n").toString();}
}
